(()=>{'use strict';const options=JSON.parse(document.getElementById('site-options')?.textContent||'{}'),ui=options.ui||{},copy=document.getElementById('page-copy');let language='en';try{language=localStorage.getItem('kenny-language')||'en'}catch{}if(!ui[language])language='en';const text=k=>ui[language]?.[k]||ui.en?.[k]||k;function localize(){if(copy){const bodies=JSON.parse(copy.textContent);document.querySelector('#service-content').innerHTML=bodies[language];document.documentElement.lang=language==='zh'?'zh-CN':language;document.querySelectorAll('[data-ui]').forEach(el=>el.textContent=text(el.dataset.ui));document.getElementById('page-language').value=language}const label=document.querySelector('label[for=page-language]');if(label)label.textContent=text('language');document.querySelector('#page-language')?.setAttribute('aria-label',text('language'))}localize();document.getElementById('page-language')?.addEventListener('change',e=>{language=e.target.value;try{localStorage.setItem('kenny-language',language)}catch{}localize()});const menu=document.querySelector('.service-menu'),nav=document.querySelector('.service-nav');menu?.addEventListener('click',()=>{const open=nav.classList.toggle('is-open');menu.setAttribute('aria-expanded',String(open));menu.textContent=text(open?'close':'menu')});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('is-open')){nav.classList.remove('is-open');menu.setAttribute('aria-expanded','false');menu.textContent=text('menu');menu.focus()}});const tracking=options.tracking||{},enabled=!!(tracking.ga4||tracking.gtm);let started=false;function readConsent(){try{return localStorage.getItem('kenny-analytics-consent')}catch{return null}}function loadAnalytics(){if(started||!enabled)return;started=true;window.dataLayer=window.dataLayer||[];window.gtag=function(){window.dataLayer.push(arguments)};window.gtag('consent','default',{analytics_storage:'denied',ad_storage:'denied',ad_user_data:'denied',ad_personalization:'denied'});window.gtag('consent','update',{analytics_storage:'granted'});if(tracking.ga4){window.gtag('js',new Date);window.gtag('config',tracking.ga4);const s=document.createElement('script');s.async=true;s.src='https://www.googletagmanager.com/gtag/js?id='+encodeURIComponent(tracking.ga4);document.head.append(s)}else{window.dataLayer.push({event:'gtm.js','gtm.start':Date.now()});const s=document.createElement('script');s.async=true;s.src='https://www.googletagmanager.com/gtm.js?id='+encodeURIComponent(tracking.gtm);document.head.append(s)}}function showConsent(){if(!enabled)return;let banner=document.querySelector('.analytics-banner');if(!banner){banner=document.createElement('section');banner.className='analytics-banner';banner.setAttribute('role','region');banner.setAttribute('aria-label',text('analytics'));document.body.append(banner)}banner.replaceChildren();const p=document.createElement('p');p.textContent=text('consent');banner.append(p);for(const [id,key]of [['granted','allow'],['denied','deny']]){const button=document.createElement('button');button.type='button';button.textContent=text(key);button.onclick=()=>{try{localStorage.setItem('kenny-analytics-consent',id)}catch{}banner.hidden=true;if(id==='granted')loadAnalytics();else if(started){window.gtag?.('consent','update',{analytics_storage:'denied',ad_storage:'denied',ad_user_data:'denied',ad_personalization:'denied'});location.reload()}};banner.append(button)}banner.hidden=false}document.addEventListener('click',e=>{if(e.target.closest('.analytics-settings'))showConsent()});if(enabled){const c=readConsent();if(c==='granted')loadAnalytics();else if(c!=='denied')showConsent()}else document.querySelectorAll('.analytics-settings').forEach(el=>el.hidden=true);})();
